/*
 * Private ARM32 stock H.264 decoder exercise; never an Android media service.
 * Recovered against the supplied 8.1 libvcodecdrv.so (REA records under
 * out/a1260-runtime-pm/vcodec-next/rea-{init-driver,h264-init-ex,drv-decode,
 * h264-decode,drv-getparam,h264-findframe,h264-dispframe}.json).
 *
 * Fixture: bitstream/pattern-128x96.h264, BASE/CAVLC, eight one-slice frames,
 * generated by local libavc avcenc. Software avcdec output equals encoder
 * reconstruction. Pass decoded-128x96.yuv as the reference. This deliberately
 * avoids I_PCM-only streams that might produce pixels without doing HW work.
 *
 * Usage: stock-decode-probe PRIVATE_LIB BITSTREAM REFERENCE_YUV OUTPUT_YUV
 * Use the private VAL/control bridge and isolated stock dependency directory.
 * Output planes are taken from the recovered codec state and row-normalized
 * to tightly packed I420 before exact comparison with the reference.
 * Pixel equality alone is not reported as HW decoding: valid-job IRQ counters
 * must increase and timeout counters must remain unchanged as well.
 */
#define _FILE_OFFSET_BITS 64
#include <dlfcn.h>
#include <errno.h>
#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/syscall.h>
#include <unistd.h>

#define WIDTH 128u
#define HEIGHT 96u
#define FRAMES 8u
#define UNITS 64u
#define FRAME_BYTES (WIDTH * HEIGHT * 3u / 2u)
#define STATE_PATH "/sys/devices/platform/1500b000.video-codec/state"
#define LIMIT (32u * 1024u * 1024u)

struct val_memory {
	uint32_t signature, type;
	uint64_t size, va, iova;
	uint32_t alignment, pad;
	uint64_t aligned_va, aligned_iova;
	uint32_t codec, share_fd;
	uint64_t ion_handle, reserved, reserved_size;
	uint32_t ion_fd, pad_end;
};
_Static_assert(sizeof(struct val_memory) == 96, "stock ARM32 VAL ABI");
_Static_assert(offsetof(struct val_memory, aligned_va) == 40, "VAL VA ABI");

/* The known fields are extended 64-bit unions, not adjacent u32 pointers.
 * Input: VA0, IOVA8, size16, readVA24, writeVA32. Output has VA0, IOVA8,
 * size16 and flags88; additional unneeded fields are explicitly zero.
 * Blobs remain alive through DeInit: the stock library keeps their pointers.
 */
struct descriptor { _Alignas(8) uint32_t word[34]; };
_Static_assert(sizeof(struct descriptor) == 0x88, "stock frame descriptor ABI");
struct image_layout { uint32_t stride, chroma_stride, lines, order; };
struct nal { size_t offset, bytes; unsigned int type; };
struct counters { uint64_t irqs, timeouts; int valid; };
static int (*val_alloc)(struct val_memory *, uint32_t);
static int (*val_free)(struct val_memory *, uint32_t);
static int (*val_flush)(struct val_memory *, uint32_t, uint32_t);
static int (*val_invalidate)(struct val_memory *, uint32_t, uint32_t);
static int (*get_param)(void *, uint32_t, void *, void *);
static struct val_memory output_memory[UNITS];
static struct descriptor output_desc[UNITS];
static uint8_t *reference;
static FILE *output;
static unsigned int displayed;

static void *read_file(const char *name, size_t *bytes)
{
	FILE *f = fopen(name, "rb");
	long n;
	void *p;
	if (!f || fseek(f, 0, SEEK_END) || (n = ftell(f)) <= 0 || (unsigned long)n > LIMIT ||
	    fseek(f, 0, SEEK_SET)) {
		if (f) fclose(f);
		return NULL;
	}
	p = malloc((size_t)n);
	if (!p || fread(p, 1, (size_t)n, f) != (size_t)n) {
		free(p); fclose(f); return NULL;
	}
	fclose(f);
	*bytes = (size_t)n;
	return p;
}

static struct counters counters(const char *phase)
{
	char text[2048];
	struct counters c = {0};
	FILE *f = fopen(STATE_PATH, "r");
	if (f) {
		size_t bytes = fread(text, 1, sizeof(text) - 1, f);
		char *irq, *timeout;
		text[bytes] = 0;
		fclose(f);
		printf("KERNEL_%s %s\n", phase, text);
		irq = strstr(text, "irqs=");
		timeout = strstr(text, "timeouts=");
		if (irq && timeout) {
			c.irqs = strtoull(irq + 5, NULL, 10);
			c.timeouts = strtoull(timeout + 9, NULL, 10);
			c.valid = 1;
		}
	} else {
		printf("KERNEL_%s unavailable errno=%d\n", phase, errno);
	}
	return c;
}

static int allocate(struct val_memory *m, uint32_t bytes)
{
	memset(m, 0, sizeof(*m));
	/* Device-coherent external fixture buffers; no cached CPU access is
	 * left open across the actual hardware job by this probe.
	 */
	m->type = 3;
	m->codec = 1;
	m->size = bytes;
	m->alignment = 4096;
	if (val_alloc(m, sizeof(*m)) || !m->va || !m->iova ||
	    m->va > UINT32_MAX || m->iova > UINT32_MAX ||
	    (m->va & 4095) || (m->iova & 4095))
		return -1;
	return 0;
}

static void descriptor(struct descriptor *d, struct val_memory *m,
		       uint32_t bytes, int input)
{
	memset(d, 0, sizeof(*d));
	d->word[0] = (uint32_t)m->va;
	d->word[2] = (uint32_t)m->iova;
	d->word[4] = bytes;
	if (input) {
		d->word[6] = (uint32_t)m->va;
		d->word[8] = (uint32_t)m->va + bytes;
	}
}

static uint32_t fnv(const uint8_t *p, size_t bytes)
{
	uint32_t hash = 2166136261u;
	for (size_t i = 0; i < bytes; ++i) hash = (hash ^ p[i]) * 16777619u;
	return hash;
}

static int drain(void *instance, const struct image_layout *layout)
{
	for (unsigned int n = 0; n < 64; ++n) {
		uint32_t returned = 0;
		uint8_t packed[FRAME_BYTES];
		uint8_t *y, *u, *v;
		size_t ys = (size_t)layout->stride * layout->lines;
		size_t cs = (size_t)layout->chroma_stride * (layout->lines / 2);
		unsigned int index;
		int rc = get_param(instance, 2, NULL, &returned);
		if (rc) { printf("DISPLAY_QUERY_FAIL rc=%d\n", rc); return -1; }
		if (!returned) return 0;
		for (index = 0; index < UNITS; ++index)
			if (returned == (uintptr_t)&output_desc[index]) break;
		if (index == UNITS || displayed == FRAMES) {
			printf("UNEXPECTED_DISPLAY_DESCRIPTOR=%08x\n", returned);
			return -1;
		}
		if (val_invalidate(&output_memory[index], sizeof(struct val_memory), 1))
			return -1;
		y = (uint8_t *)(uintptr_t)output_memory[index].va;
		u = y + ys;
		v = u + cs;
		if (layout->order) { uint8_t *tmp = u; u = v; v = tmp; }
		for (unsigned int row = 0; row < HEIGHT; ++row)
			memcpy(packed + row * WIDTH, y + row * layout->stride, WIDTH);
		for (unsigned int row = 0; row < HEIGHT / 2; ++row) {
			memcpy(packed + WIDTH * HEIGHT + row * (WIDTH / 2),
			       u + row * layout->chroma_stride, WIDTH / 2);
			memcpy(packed + WIDTH * HEIGHT * 5 / 4 + row * (WIDTH / 2),
			       v + row * layout->chroma_stride, WIDTH / 2);
		}
		if (fwrite(packed, 1, sizeof(packed), output) != sizeof(packed)) return -1;
		uint8_t *expected = reference + displayed * FRAME_BYTES;
		if (memcmp(packed, expected, sizeof(packed))) {
			unsigned int errors = 0, max_delta = 0;
			for (size_t i = 0; i < sizeof(packed); ++i) {
				unsigned int delta = abs((int)packed[i] - (int)expected[i]);
				errors += delta != 0;
				if (delta > max_delta) max_delta = delta;
			}
			printf("FRAME_MISMATCH n=%u buffer=%u errors=%u max_delta=%u fnv=%08x expected=%08x\n",
			       displayed, index, errors, max_delta, fnv(packed, sizeof(packed)),
			       fnv(expected, sizeof(packed)));
			return -1;
		}
		printf("FRAME_MATCH n=%u buffer=%u bytes=%u fnv=%08x\n",
		       displayed, index, FRAME_BYTES, fnv(packed, sizeof(packed)));
		displayed++;
	}
	puts("DISPLAY_QUERY_DID_NOT_DRAIN");
	return -1;
}

int main(int argc, char **argv)
{
	int (*create)(void **, uint32_t), (*init)(void *, void *, void *);
	int (*decode)(void *, void *, void *), (*deinit)(void *), (*release)(void *);
	int (*set_param)(void *, uint32_t, void *);
	struct val_memory input_memory[UNITS] = {{0}}, csd_memory = {0};
	struct descriptor input_desc[UNITS], csd_desc;
	struct image_layout layout;
	struct counters before, after;
	struct nal nals[64];
	uint32_t picture[64] = {0};
	uint8_t *stream = NULL;
	void *library = NULL, *instance = NULL;
	size_t stream_bytes = 0, reference_bytes = 0, nal_count = 0, csd_bytes = 0;
	unsigned int input_count = 0, initialized = 0;
	int result = 1, rc;
	setbuf(stdout, NULL);
	if (sizeof(void *) != 4 || argc != 5) {
		fprintf(stderr, "ARM32 only: %s PRIVATE_LIB BITSTREAM REFERENCE_I420 OUTPUT_I420\n", argv[0]);
		return 2;
	}
	stream = read_file(argv[2], &stream_bytes);
	reference = read_file(argv[3], &reference_bytes);
	if (!stream || !reference || reference_bytes != FRAMES * FRAME_BYTES) goto done;
	for (size_t i = 0; i + 4 < stream_bytes;) {
		unsigned int prefix = !memcmp(stream + i, "\0\0\0\1", 4) ? 4 :
			!memcmp(stream + i, "\0\0\1", 3) ? 3 : 0;
		if (!prefix) { i++; continue; }
		if (nal_count == sizeof(nals) / sizeof(nals[0])) goto done;
		if (nal_count) nals[nal_count - 1].bytes = i - nals[nal_count - 1].offset;
		nals[nal_count++] = (struct nal){i, stream_bytes - i, stream[i + prefix] & 31};
		i += prefix;
	}
	for (size_t i = 0; i < nal_count; ++i) {
		if (nals[i].type == 7 || nals[i].type == 8) csd_bytes += nals[i].bytes;
		if (nals[i].type == 1 || nals[i].type == 5) input_count++;
	}
	if (!csd_bytes || csd_bytes > 4096 || input_count != FRAMES) goto done;
	library = dlopen(argv[1], RTLD_NOW | RTLD_LOCAL);
	if (!library) { puts(dlerror()); goto done; }
#define SYM(dst, source, name) do { dst = dlsym(source, name); if (!dst) { puts("MISSING " name); goto done; } } while (0)
	SYM(create, library, "eVDecDrvCreate");
	SYM(init, library, "eVDecDrvInit");
	SYM(decode, library, "eVDecDrvDecode");
	SYM(get_param, library, "eVDecDrvGetParam");
	SYM(set_param, library, "eVDecDrvSetParam");
	SYM(deinit, library, "eVDecDrvDeInit");
	SYM(release, library, "eVDecDrvRelease");
	SYM(val_alloc, RTLD_DEFAULT, "eVideoMemAlloc");
	SYM(val_free, RTLD_DEFAULT, "eVideoMemFree");
	SYM(val_flush, RTLD_DEFAULT, "eVideoFlushCache");
	SYM(val_invalidate, RTLD_DEFAULT, "eVideoInvalidateCache");
	if (allocate(&csd_memory, csd_bytes + 64)) goto done;
	csd_bytes = 0;
	for (size_t i = 0; i < nal_count; ++i) if (nals[i].type == 7 || nals[i].type == 8) {
		memcpy((uint8_t *)(uintptr_t)csd_memory.va + csd_bytes,
		       stream + nals[i].offset, nals[i].bytes);
		csd_bytes += nals[i].bytes;
	}
	descriptor(&csd_desc, &csd_memory, csd_bytes, 1);
	if (val_flush(&csd_memory, sizeof(csd_memory), 1)) goto done;
	(void)counters("BEFORE_INIT");
	rc = create(&instance, 0x100);
	printf("CREATE rc=%d instance=%p\n", rc, instance);
	if (rc || !instance) goto done;
	/* SetParam 0xf stores the packed OMX input/output Linux TIDs at
	 * instance+0x338. InitEx passes that to set_threads, which prepends
	 * high16/low16 to the codec HW-worker TIDs. Our fixture runs both OMX
	 * roles on this actual thread; zero/default tokens are not real TIDs.
	 */
	long tid = syscall(__NR_gettid);
	if (tid <= 0 || tid > UINT16_MAX) {
		puts("LEGACY_PACKED_TID_OUT_OF_RANGE");
		goto done;
	}
	uint32_t packed_tids = (uint32_t)tid << 16 | (uint32_t)tid;
	rc = set_param(instance, 0xf, &packed_tids);
	printf("OMX_THREADS tid=%ld packed=%08x setparam_rc=%d\n", tid, packed_tids, rc);
	if (rc) goto done;
	rc = init(instance, &csd_desc, picture);
	printf("INIT rc=%d picture=%u,%u real=%u,%u buffer=%u,%u\n", rc,
	       picture[0], picture[1], picture[2], picture[3], picture[4], picture[5]);
	/* Actual stock execution: success is 0. The internal codec callback
	 * returns boolean success 1; the wrapper maps callback 0 to API error 1.
	 * Missing codec dependencies returned 1/picture0, while valid Init
	 * returned 0/128x96. Do not confuse the two interfaces' return values.
	 */
	if (rc) goto done;
	initialized = 1;
	if (picture[0] != WIDTH || picture[1] != HEIGHT) goto done;
	/* Exact recovered 8.1 codec-state fields, not a generic ABI promise. */
	uint32_t *codec = (uint32_t *)(uintptr_t)((uint32_t *)instance)[0xb];
	if (!codec) goto done;
	layout = (struct image_layout){codec[600], codec[0x259],
		(codec[0x249] + 15) & ~15u, codec[0x25a]};
	printf("LAYOUT stride=%u chroma_stride=%u lines=%u order=%u\n",
	       layout.stride, layout.chroma_stride, layout.lines, layout.order);
	if (layout.stride < WIDTH || layout.stride > 4096 ||
	    layout.chroma_stride < WIDTH / 2 || layout.chroma_stride > 2048 ||
	    layout.lines < HEIGHT || layout.lines > 1088 || layout.order > 1) goto done;
	if (getenv("MT6580_PROBE_INIT_ONLY")) {
		puts("INIT_ONLY_REQUESTED (no decode performed, not HW qualification)");
		result = 0;
		goto done;
	}
	/* Init may touch hardware; only IRQs during actual Decode/flush count. */
	before = counters("BEFORE_DECODE");
	output = fopen(argv[4], "wb");
	if (!output) goto done;
	input_count = 0;
	for (size_t i = 0; i < nal_count; ++i) {
		if (nals[i].type != 1 && nals[i].type != 5 && nals[i].type != 7 && nals[i].type != 8) continue;
		unsigned int index = input_count++;
		uint32_t span = layout.lines * (layout.stride + layout.chroma_stride);
		if (nals[i].bytes > LIMIT - 64 || allocate(&input_memory[index], nals[i].bytes + 64) ||
		    allocate(&output_memory[index], span + 4096)) goto done;
		memset((void *)(uintptr_t)input_memory[index].va, 0, nals[i].bytes + 64);
		memcpy((void *)(uintptr_t)input_memory[index].va, stream + nals[i].offset, nals[i].bytes);
		memset((void *)(uintptr_t)output_memory[index].va, 0xdd, span + 4096);
		descriptor(&input_desc[index], &input_memory[index], nals[i].bytes, 1);
		descriptor(&output_desc[index], &output_memory[index], span, 0);
		if (val_flush(&input_memory[index], sizeof(struct val_memory), 1) ||
		    val_flush(&output_memory[index], sizeof(struct val_memory), 1)) goto done;
		rc = decode(instance, &input_desc[index], &output_desc[index]);
		printf("DECODE n=%u nal=%u bytes=%zu rc=%d flags=%08x\n",
		       index, nals[i].type, nals[i].bytes, rc, output_desc[index].word[22]);
		if (rc) goto done;
		if ((nals[i].type == 1 || nals[i].type == 5) && drain(instance, &layout)) goto done;
	}
	rc = decode(instance, NULL, NULL);
	printf("FLUSH rc=%d\n", rc);
	if (rc || drain(instance, &layout) || displayed != FRAMES) goto done;
	after = counters("AFTER");
	if (fflush(output)) goto done;
	if (!before.valid || !after.valid) {
		puts("FRAMES_MATCH_NEEDS_IRQ_EVIDENCE (kernel counters unavailable)");
		result = 3;
		goto done;
	}
	printf("IRQ_DELTA=%" PRIu64 " TIMEOUT_DELTA=%" PRIu64 "\n",
	       after.irqs - before.irqs, after.timeouts - before.timeouts);
	if (after.irqs <= before.irqs || after.timeouts != before.timeouts) goto done;
	puts("HARDWARE_DECODE_CONFIRMED frames=8 exact_I420_reference_match=1 real_IRQ_delta_positive=1");
	result = 0;
done:
	printf("PROBE_RESULT=%d displayed=%u\n", result, displayed);
	/* DeInit success is 0, confirmed by real stock execution. It cleans partially started
	 * VAL/HAL contexts after an Init failure; their wrapper flags are the
	 * recovered bytes at 0x30/0x38/0x40.
	 */
	if (instance && (initialized || ((uint8_t *)instance)[0x30] ||
	    ((uint8_t *)instance)[0x38] || ((uint8_t *)instance)[0x40])) {
		rc = deinit(instance);
		printf("DEINIT rc=%d\n", rc);
		if (initialized && rc) result = 1;
	}
	if (instance) printf("RELEASE rc=%d\n", release(instance));
	if (val_free) {
		for (unsigned int i = 0; i < UNITS; ++i) {
			if (input_memory[i].va) val_free(&input_memory[i], sizeof(struct val_memory));
			if (output_memory[i].va) val_free(&output_memory[i], sizeof(struct val_memory));
		}
		if (csd_memory.va) val_free(&csd_memory, sizeof(csd_memory));
	}
	if (output) fclose(output);
	if (library) dlclose(library);
	free(reference);
	free(stream);
	return result;
}
